    if n == 0: return []
    a=[1]; forbidden: Set[int]=set()
    while len(a)<n:
        x=a[-1]
        for y in a[:-1]: forbidden.add(x+y)
        z=x+1
        while z in forbidden: z+=1
        a.append(z)
    return a

from typing import List
def term(n: int) -> int:
    if n < 0: raise ValueError("n must be nonnegative")
    return 1 if n == 0 else 2 if n == 1 else 3*n-2
def prefix(n: int) -> List[int]:
    return [term(k) for k in range(n)]

from typing import Optional
def index_of(x: int) -> Optional[int]:
    if x == 1: return 0
    if x == 2: return 1
    if x >= 4 and x % 3 == 1: return (x+2)//3
    return None
def count_through(n: int) -> int:
    if n < 1: return 0
